#!/usr/bin/env python3
"""Exact source-replay wrapper for TMR-3/066's executed CPython audit.

The complete original executable is zlib-compressed here, not reconstructed
from test outputs. SHA256 is checked before executing its entrypoint.
"""
import base64
import hashlib
import zlib

ORIGINAL_SHA256 = "798de9d0980c4c59cd86f0b81548cf3f8883525775e9888be0534f5437793ae4"
COMPRESSED_BASE64 = ""
source = zlib.decompress(base64.b64decode(COMPRESSED_BASE64))
assert hashlib.sha256(source).hexdigest() == ORIGINAL_SHA256, "source SHA mismatch"
exec(compile(source, __file__, "exec"), {"__name__": "__main__", "__file__": __file__})
